-- Sasaran energi disamakan dengan Formulir Objective dan Target Manajemen SMEn (klausul 6.2, 001/SOP-008/KINRA/SMEn/X/2026),
-- folder OneDrive "Formulir Sasaran & Target (KINRA)", 10 bagian, periode 2026.
-- 1) Empat sasaran kinerja energi buatan aplikasi (ENPI-04, ENPI-05, ENPI-06, ENPI-01; migrasi 0041) dihapus karena tidak ada
--    di formulir mana pun. Rencana aksinya TIDAK dihapus; sasaran_id menjadi kosong (on delete set null).
-- 2) Sasaran per bagian dari formulir dimuat (kode SB-<no bagian>-<no>). Pencapaian diambil dari sheet "Pencapaian <bulan>"
--    terakhir yang tanggalnya tidak melewati 2026-11-11; sheet bertanggal di masa depan (30 November 2026) diabaikan.
-- Jalankan setelah 0047. Aman diulang: baris dari formulir dimuat ulang, sasaran lain yang ditambahkan manual tidak disentuh.

alter table sasaran add column if not exists bagian text;
alter table sasaran add column if not exists aktivitas text;
alter table sasaran add column if not exists aspek text;
alter table sasaran add column if not exists target_teks text;
alter table sasaran add column if not exists program text;
alter table sasaran add column if not exists batas_waktu text;
alter table sasaran add column if not exists pencapaian text;
alter table sasaran add column if not exists pencapaian_per date;
alter table sasaran add column if not exists sumber text;

delete from sasaran where sumber is null and enpi_kode in ('ENPI-04', 'ENPI-05', 'ENPI-06', 'ENPI-01');
delete from sasaran where sumber like 'Formulir Sasaran 6.2%';

